CREATE DATABASE IF NOT EXISTS kopi_jago_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kopi_jago_db;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS ratings,order_assignment_audit,password_reset_tokens,seller_profiles,inventory_stock,support_messages,notifications,wishlist,order_items,orders,cart_items,addresses,promos,vehicles,menu_items,menu_categories,auth_tokens,users,roles;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE roles (id TINYINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(20) UNIQUE NOT NULL,description VARCHAR(150));
CREATE TABLE users (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,role_id TINYINT UNSIGNED NOT NULL DEFAULT 1,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,phone VARCHAR(30),birth_date DATE NULL,password_hash VARCHAR(255) NOT NULL,is_active BOOLEAN NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE auth_tokens (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id INT UNSIGNED NOT NULL,token_hash CHAR(64) UNIQUE NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE password_reset_tokens (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id INT UNSIGNED NOT NULL,token_hash CHAR(64) UNIQUE NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE menu_categories (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,slug VARCHAR(80) UNIQUE NOT NULL);
CREATE TABLE menu_items (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,category_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,description TEXT,price DECIMAL(12,2) NOT NULL,is_available BOOLEAN DEFAULT 1,is_featured BOOLEAN DEFAULT 0,FOREIGN KEY(category_id) REFERENCES menu_categories(id));
CREATE TABLE inventory_stock (menu_id INT UNSIGNED PRIMARY KEY,stock INT UNSIGNED NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(menu_id) REFERENCES menu_items(id) ON DELETE CASCADE);
CREATE TABLE vehicles (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,seller_id INT UNSIGNED NOT NULL,type ENUM('sepeda','sepeda_listrik') NOT NULL,plate VARCHAR(30),is_available BOOLEAN DEFAULT 1,FOREIGN KEY(seller_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE seller_profiles (user_id INT UNSIGNED PRIMARY KEY,area VARCHAR(120),vehicle_type ENUM('sepeda','sepeda_listrik') NOT NULL DEFAULT 'sepeda',status ENUM('offline','available','busy','inactive') NOT NULL DEFAULT 'offline',last_latitude DECIMAL(10,7),last_longitude DECIMAL(10,7),updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE cart_items (user_id INT UNSIGNED NOT NULL,menu_id INT UNSIGNED NOT NULL,qty SMALLINT UNSIGNED NOT NULL DEFAULT 1,PRIMARY KEY(user_id,menu_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(menu_id) REFERENCES menu_items(id));
CREATE TABLE addresses (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id INT UNSIGNED NOT NULL,label VARCHAR(50),recipient_name VARCHAR(100) NOT NULL,phone VARCHAR(30) NOT NULL,address_line VARCHAR(255) NOT NULL,city VARCHAR(80) NOT NULL,province VARCHAR(80) NOT NULL,postal_code VARCHAR(10),is_default BOOLEAN DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE promos (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(120) NOT NULL,discount_type ENUM('percentage','fixed') NOT NULL,discount_value DECIMAL(12,2) NOT NULL,min_purchase DECIMAL(12,2) DEFAULT 0,start_date DATE NOT NULL,end_date DATE NOT NULL,usage_limit INT UNSIGNED,is_active BOOLEAN DEFAULT 1);
CREATE TABLE orders (id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,order_number VARCHAR(40) UNIQUE NOT NULL, user_id INT UNSIGNED NOT NULL,vehicle_id INT UNSIGNED NULL,status ENUM('pending','confirmed','processing','ready','on_delivery','completed','cancelled') DEFAULT 'pending',fulfillment_type ENUM('pickup','delivery') NOT NULL DEFAULT 'delivery',subtotal DECIMAL(12,2) NOT NULL,discount_amount DECIMAL(12,2) DEFAULT 0,shipping_cost DECIMAL(12,2) DEFAULT 0,total_amount DECIMAL(12,2) NOT NULL,payment_method ENUM('cash','qris','ewallet','bank_transfer') NOT NULL DEFAULT 'cash',payment_status ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending',address_id INT UNSIGNED NULL,notes VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE SET NULL,FOREIGN KEY(address_id) REFERENCES addresses(id) ON DELETE SET NULL,CHECK (subtotal >= 0 AND discount_amount >= 0 AND shipping_cost >= 0 AND total_amount >= 0),CHECK ((fulfillment_type = 'pickup' AND address_id IS NULL) OR (fulfillment_type = 'delivery' AND address_id IS NOT NULL)));
CREATE TABLE order_items (order_id INT UNSIGNED NOT NULL,menu_id INT UNSIGNED NOT NULL,qty SMALLINT UNSIGNED NOT NULL,price DECIMAL(12,2) NOT NULL,PRIMARY KEY(order_id,menu_id),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(menu_id) REFERENCES menu_items(id));
CREATE TABLE wishlist (user_id INT UNSIGNED NOT NULL,menu_id INT UNSIGNED NOT NULL,PRIMARY KEY(user_id,menu_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(menu_id) REFERENCES menu_items(id) ON DELETE CASCADE);
CREATE TABLE notifications (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id INT UNSIGNED NOT NULL,title VARCHAR(150) NOT NULL,message TEXT NOT NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE support_messages (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id INT UNSIGNED NOT NULL,sender_role ENUM('customer','admin') NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE ratings (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,order_id INT UNSIGNED NOT NULL,menu_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,score TINYINT UNSIGNED NOT NULL,review TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY one_rating(order_id,menu_id,user_id),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(menu_id) REFERENCES menu_items(id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CHECK(score BETWEEN 1 AND 5));
CREATE TABLE order_assignment_audit (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,order_id INT UNSIGNED NOT NULL,vehicle_id INT UNSIGNED NULL,admin_id INT UNSIGNED NOT NULL,action VARCHAR(30) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE SET NULL,FOREIGN KEY(admin_id) REFERENCES users(id));
